#!/bin/sh
# Generates the machine-local pubspec_overrides.yaml that resolves
# `e_livre` from the sibling eLivre checkout, mirroring the local stack
# layout:
#
#   <parent>/eLivre
#   <parent>/e_livre_viewer   <- this repository
#
# The generated file is gitignored on purpose: the committed contract stays
# on the hosted `e_livre: ^3.0.0` constraint in pubspec.yaml, and the
# multi-repo CI integration lane runs this same script in-job.
#
# Usage: tool/generate_local_overrides.sh
set -eu

root="$(cd "$(dirname "$0")/.." && pwd)"

if [ ! -d "$root/../eLivre" ]; then
  echo "error: sibling eLivre checkout not found at $root/../eLivre" >&2
  echo "       clone https://github.com/KaiqueFarias09/eLivre next to this" >&2
  echo "       repository, or let CI's integration lane do it for you" >&2
  exit 1
fi

cat > "$root/pubspec_overrides.yaml" <<'EOF'
# Generated by tool/generate_local_overrides.sh. Machine-local, do not commit.
dependency_overrides:
  e_livre:
    path: ../eLivre
EOF

echo "generated $root/pubspec_overrides.yaml (e_livre -> ../eLivre)"
